<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {gamesApi,type GameMetadata} from '@/api/games'
const games=ref<GameMetadata[]>([]),loading=ref(false),error=ref(''),selected=ref<GameMetadata|null>(null),rulesOpen=ref(false),router=useRouter()
async function load(){loading.value=true;error.value='';try{games.value=await gamesApi.list()}catch(e){error.value=e instanceof Error?e.message:'游戏加载失败'}finally{loading.value=false}}
onMounted(load)
</script>
<template><section class="games-page"><header><span>和同频的人，一起进入游戏</span><h1>游戏 <small>PLAY TOGETHER</small></h1></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重新加载</el-button><div class="games-grid" v-loading="loading"><article v-for="game in games" :key="game.type" class="game-card"><img :src="game.poster" :alt="`${game.name}海报`"/><div class="game-card-body"><div class="game-card-title"><h2>{{game.name}}</h2><el-tag :type="game.status==='AVAILABLE'?'success':'info'" round>{{game.status==='AVAILABLE'?'可游玩':'维护中'}}</el-tag></div><span class="game-category">{{game.category}} · {{game.minPlayers}}—{{game.maxPlayers}} 人</span><p>{{game.description}}</p><div class="recommended">推荐人数 <span v-for="n in game.recommendedPlayers" :key="n">{{n}} 人</span></div><div class="game-card-actions"><el-button type="primary" :disabled="game.status!=='AVAILABLE'" @click="router.push(game.lobbyPath)">进入大厅</el-button><el-button @click="selected=game;rulesOpen=true">玩法介绍</el-button></div></div></article></div><p class="catalogue-note">选择游戏后，可在大厅创建房间、加入公开房间或按配置匹配。</p><el-dialog v-model="rulesOpen" :title="`${selected?.name||''} · 玩法介绍`" width="min(540px,94vw)"><p v-for="(rule,index) in selected?.rules" :key="index" class="rule-row">{{index+1}}. {{rule}}</p><template #footer><el-button type="primary" @click="rulesOpen=false;router.push(selected!.lobbyPath)">进入大厅</el-button></template></el-dialog></section></template>
<style scoped>.games-page{max-width:1180px;margin:20px auto}.games-page header>span{font-size:12px;color:var(--ww-text-dim)}h1{font-size:32px;margin:12px 0 26px}h1 small{font-size:11px;letter-spacing:3px;color:#b4a5c9;margin-left:14px}.games-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,540px));gap:24px;min-height:240px}.game-card{overflow:hidden;border-radius:22px;border:1px solid var(--ww-border);background:rgba(22,27,47,.9)}.game-card>img{display:block;width:100%;aspect-ratio:16/9;object-fit:contain;background:#fff}.game-card-body{padding:24px}.game-card-title{display:flex;align-items:center;justify-content:space-between}.game-card-title h2{font-size:24px;margin:0 0 10px}.game-category{color:#d2b987;font-size:12px}.game-card p{color:var(--ww-text-dim);font-size:13px;line-height:1.9;max-width:440px}.recommended{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:11px;color:var(--ww-text-dim);margin:20px 0}.recommended span{border:1px solid var(--ww-border);border-radius:6px;padding:4px 9px}.game-card-actions{display:flex;gap:10px}.catalogue-note{font-size:12px;color:var(--ww-text-dim);margin-top:24px}.rule-row{font-size:14px;line-height:1.9}@media(max-width:680px){.games-page{margin:8px auto}.games-grid{grid-template-columns:minmax(0,1fr)}.game-card-body{padding:20px}h1{font-size:28px}.game-card{border-radius:16px}}</style>
